def clamp(value, minimum, maximum):
    if value < minimum:
        return minimum
    if value > maximum:
        return maximum
    return value

def dedupe_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def largest(numbers):
    result = numbers[0]
    for number in numbers:
        if number > result:
            result = number
    return result

def flatten_dict(data, prefix=''):
    result = {}
    for key, value in data.items():
        new_key = f"{prefix}{key}"
        if isinstance(value, dict):
            result.update(flatten_dict(value, f"{new_key}."))
        else:
            result[new_key] = value
    return result
